import itertools, numpy as np
funcs=list(itertools.product(range(5), repeat=5))
def maxcycle(f):
    best=0
    for s in range(5):
        x=s
        for t in range(1,6):
            x=f[x]
            if x==s: best=max(best,t); break
    return best-1
def classify(f):
    F=np.array(f)
    G=np.array([f[f[i]] for i in range(5)])
    H=np.array([f[f[f[f[i]]]] for i in range(5)])
    Fs=[F,G,np.array([F[G[i]] for i in range(5)]),H,np.array([F[H[i]] for i in range(5)])]
    best=0
    for s in range(5):
        for k,Fk in enumerate(Fs,1):
            if Fk[s]==s:
                best=max(best,k); break
    return best-1
bad=0
for f in funcs:
    if classify(f)!=maxcycle(f):
        bad+=1
        if bad<5: print('bad',f,classify(f),maxcycle(f))
